#include <print>
#include <vector>

int main() {
    std::vector<int> v = {3, 9, 4};
    int best = v[0];
    for (size_t i = 1; i < v.size(); ++i)
        if (v[i] > best) best = v[i];
    std::println("最大值是 {}", best);
    long long big = 1;
    int small = 1;
    for (int i = 0; i < 13; ++i) { big *= 10; small *= 10; }
    std::println("long long = {}", big);
    std::println("int 换上去 = {}", small);
    return 0;
}

